            aIngress ^= (RotL64(aFireLaneC[((aIndex + 9685U)) & S_BLOCK1], 21U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 12151U)) & S_BLOCK1], 10U));
