            aWandererA = aWandererA + ((((RotL64(aPrevious, 3U) + RotL64(aOrbiterF, 21U)) + aOrbiterA) + RotL64(aCarry, 41U)) + aPhaseDWandererUpdateSaltD[((aIndex + 28U)) & S_SALT1]);
