            aOrbiterA = (aWandererG + RotL64(aPrevious, 5U)) + 0x395E7AFA9EA88E65ULL;
            aOrbiterE = ((aWandererH + RotL64(aScatter, 13U)) + 0x573E9688809BE316ULL) + aPhaseCOrbiterAssignSaltA[(((31U - aIndex) + 18U)) & S_SALT1];
