            aOrbiterI = (((aWandererK + RotL64(aPrevious, 41U)) + RotL64(aCarry, 51U)) + 0xEE61A432C7A65DD0ULL) + aPhaseCOrbiterAssignSaltD[((aIndex + 6U)) & S_SALT1];
