            aOrbiterG = (aWandererA + RotL64(aCross, 35U)) + 0x906D0A76D6B50D34ULL;
            aOrbiterF = ((aWandererF + RotL64(aPrevious, 27U)) + RotL64(aCarry, 27U)) + 0x9B82ED74F5AD1583ULL;
            aOrbiterH = (aWandererC + RotL64(aIngress, 11U)) + 0x2BB4D09C96709C57ULL;
