            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0xD131E650664B8CA4ULL) + aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0xBF96ABB03E0E2F2BULL;
