            aOrbiterE = (((aWandererG + RotL64(aPrevious, 29U)) + RotL64(aCarry, 29U)) + 0xB072A18541096E8FULL) + aPhaseCOrbiterAssignSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterJ = (aWandererI + RotL64(aScatter, 11U)) + 0x8795AC6A8E6CA147ULL;
            aOrbiterG = ((aWandererH + RotL64(aIngress, 57U)) + RotL64(aCarry, 3U)) + 0x0FC543B2D85E4598ULL;
            aOrbiterF = ((aWandererJ + RotL64(aCross, 41U)) + 0x997C6DC2A0B5A963ULL) + aPhaseCOrbiterAssignSaltF[((aIndex + 16U)) & S_SALT1];
            aOrbiterC = (aWandererB + RotL64(aScatter, 47U)) + 0xE5C4C15F091F1783ULL;
            //
