            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0x4D9C9B890F06C3F4ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x8B93CDF8C781A929ULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xC3510F74E95F6A2DULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0x671091631134BE68ULL) ^ aPhaseCOrbiterUpdateSaltD[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x2F341CA084282C0DULL), 35U);
